#include <bits/stdc++.h>
using namespace std;
const int INF=1e9;
int n; vector<vector<int>> g; vector<int> rem, sz, par, best, p2;
vector<vector<pair<int,int>>> anc;   // per vertex: (centroid, dist)
void decompose(int r){
    vector<int> ord{r}; par[r]=0;
    for(size_t i=0;i<ord.size();i++) for(int w:g[ord[i]]) if(!rem[w]&&w!=par[ord[i]]){ par[w]=ord[i]; ord.push_back(w); }
    for(int i=ord.size()-1;i>=0;i--){ sz[ord[i]]=1; for(int w:g[ord[i]]) if(!rem[w]&&w!=par[ord[i]]) sz[ord[i]]+=sz[w]; }
    int tot=ord.size(), c=r;
    for(int v:ord){ int mx=tot-sz[v]; for(int w:g[v]) if(!rem[w]&&w!=par[v]) mx=max(mx,sz[w]); if(2*mx<=tot){ c=v; break; } }
    vector<pair<int,int>> q{{c,0}}; p2[c]=0;
    for(size_t i=0;i<q.size();i++){ auto [v,d]=q[i]; anc[v].push_back({c,d});
        for(int w:g[v]) if(!rem[w]&&w!=p2[v]){ p2[w]=v; q.push_back({w,d+1}); } }
    rem[c]=1;
    for(int w:g[c]) if(!rem[w]) decompose(w);
}
int main(){
    int t; scanf("%d",&t);
    while(t--){
        scanf("%d",&n); int c0; scanf("%d",&c0);
        vector<int> cs(n-1); for(auto& x:cs) scanf("%d",&x);
        g.assign(n+1,{}); rem.assign(n+1,0); sz.assign(n+1,0); par.assign(n+1,0); p2.assign(n+1,0);
        best.assign(n+1,INF); anc.assign(n+1,{});
        for(int i=0;i<n-1;i++){ int u,v; scanf("%d %d",&u,&v); g[u].push_back(v); g[v].push_back(u); }
        decompose(1);
        auto ins=[&](int v){ for(auto [c,d]:anc[v]) best[c]=min(best[c],d); };
        auto qry=[&](int v){ int r=INF; for(auto [c,d]:anc[v]) if(best[c]<INF) r=min(r,d+best[c]); return r; };
        ins(c0); int ans=INF;
        for(int i=0;i<n-1;i++){ ans=min(ans,qry(cs[i])); printf("%d%c",ans,i+1==n-1?'\n':' '); ins(cs[i]); }
    }
}

#include <bits/stdc++.h>
using namespace std;
int main(){
    int t; scanf("%d",&t);
    while(t--){
        int n,m; scanf("%d %d",&n,&m);
        vector<int> d(n+1); vector<vector<int>> g(n+1);
        for(int i=1;i<=n;i++) scanf("%d",&d[i]);
        for(int i=0;i<m;i++){ int u,v; scanf("%d %d",&u,&v); g[u].push_back(v); g[v].push_back(u); }
        vector<char> covered(n+1,0); vector<int> vis(n+1,0); bool yes=false;
        for(int s=1;s<=n && !yes;s++){
            if(d[s]!=0 || covered[s]) continue;     // s inside an earlier closure => its closure is a subset, skip
            // closure of s: defeat frontier vertex with smallest danger while danger <= count defeated
            priority_queue<pair<int,int>, vector<pair<int,int>>, greater<>> pq;
            pq.push({d[s],s}); vis[s]=s; int cnt=0;
            while(!pq.empty() && pq.top().first<=cnt){
                int u=pq.top().second; pq.pop(); cnt++; covered[u]=1;
                for(int w:g[u]) if(vis[w]!=s){ vis[w]=s; pq.push({d[w],w}); }
            }
            if(cnt==n) yes=true;
        }
        puts(yes?"YES":"NO");
    }
}

#include <bits/stdc++.h>
using namespace std;
int main(){
    int n,q; scanf("%d %d",&n,&q);
    static char buf[200005]; scanf("%s",buf); string s(buf);
    while(q--){
        int i; scanf("%d",&i); s[i-1]= s[i-1]=='(' ? ')' : '(';
        bool ok=false;
        if(s[0]=='(' && s[n-1]==')'){
            // BFS over states (position, balance); walk = sequence of visited positions
            vector<vector<char>> seen(n, vector<char>(n+2,0));
            deque<pair<int,int>> dq{{0,1}}; seen[0][1]=1;
            while(!dq.empty() && !ok){
                auto [p,b]=dq.front(); dq.pop_front();
                if(p==n-1 && b==0){ ok=true; break; }
                for(int d:{-1,1}){
                    int np=p+d; if(np<0||np>=n) continue;
                    int nb=b+(s[np]=='('?1:-1);
                    if(nb<0||nb>n||seen[np][nb]) continue;
                    seen[np][nb]=1; dq.push_back({np,nb});
                }
            }
        }
        puts(ok?"YES":"NO");
    }
}

#include <bits/stdc++.h>
using namespace std;
typedef unsigned long long u64;
int hb(u64 x){ return 63-__builtin_clzll(x); }
int main(){
    int t; scanf("%d",&t);
    while(t--){
        u64 n,m; scanf("%llu %llu",&n,&m);
        int h=hb(n), c=hb(m), g=-1;               // g = second highest set bit of n (-1 if none)
        u64 rest=n ^ (1ULL<<h);
        if(rest) g=hb(rest);
        if(m>=n || (c>g && c!=h)){ puts("-1"); continue; }
        if(c==h || c==g){ printf("1\n%llu %llu\n", n, m); continue; }
        // c < g: clear bit g of n, choose low bits so that bit c is set, then jump to m
        u64 low = (1ULL<<c) * (((n>>c)&1)^1);
        u64 mid = n ^ ((1ULL<<g) | low);
        printf("2\n%llu %llu %llu\n", n, mid, m);
    }
}

#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
int main(){
    int T; scanf("%d",&T);
    while(T--){
        int n,m; scanf("%d %d",&n,&m);
        ll t0,t1,t2; scanf("%lld %lld %lld",&t0,&t1,&t2);
        vector<vector<array<ll,3>>> g(n+1);
        for(int i=0;i<m;i++){ int u,v; ll l1,l2; scanf("%d %d %lld %lld",&u,&v,&l1,&l2);
            g[u].push_back({v,l1,l2}); g[v].push_back({u,l1,l2}); }
        const ll NEG=LLONG_MIN/4;
        vector<ll> f(n+1,NEG);
        priority_queue<pair<ll,int>> pq;
        f[n]=t0; pq.push({t0,n});
        while(!pq.empty()){
            auto [fv,v]=pq.top(); pq.pop();
            if(fv!=f[v]) continue;
            for(auto& e:g[v]){
                int u=e[0]; ll l1=e[1], l2=e[2];
                // walk u->v arriving by fv
                ll cand=fv-l2;
                // bus u->v departing y=fv-l1 latest; avoid riding inside (t1,t2)
                ll y=fv-l1;
                ll bus = (y>=t2 || y+l1<=t1) ? y : t1-l1;
                cand=max(cand,bus);
                if(cand>f[u]){ f[u]=cand; pq.push({cand,u}); }
            }
        }
        printf("%lld\n", f[1]<0? -1 : f[1]);
    }
}

#include <bits/stdc++.h>
using namespace std;
int main(){
    int t; scanf("%d",&t);
    while(t--){
        int n,q; scanf("%d %d",&n,&q);
        vector<int> P(n+1,0);
        for(int i=0;i<n;i++){ int a; scanf("%d",&a); P[a]++; }
        for(int v=1;v<=n;v++) P[v]+=P[v-1];
        int k=n/2+1;
        vector<int> memo(n+1,-1);
        for(int qi=0;qi<q;qi++){
            int x; scanf("%d",&x);
            if(memo[x]<0){
                auto cnt=[&](int m){ // #elements with a mod x <= m
                    long long c=0;
                    for(long long j=0;j<=n;j+=x){
                        long long hi=min<long long>(n,j+m), lo=(j>0?P[j-1]:0);
                        c+=P[hi]-lo;
                    }
                    return c;
                };
                int lo=0, hi=x-1;
                while(lo<hi){ int mid=(lo+hi)/2; if(cnt(mid)>=k) hi=mid; else lo=mid+1; }
                memo[x]=lo;
            }
            printf("%d%c", memo[x], qi+1==q?'\n':' ');
        }
    }
}

#include <bits/stdc++.h>
using namespace std;
typedef long long ll; typedef __int128 L;
int main(){
    int t; scanf("%d",&t);
    while(t--){
        int n; scanf("%d",&n);
        vector<ll> a(n+1);
        for(int i=1;i<=n;i++) scanf("%lld",&a[i]);
        // x_i = (x_{i-1}+a_i)/2 cyclic, x_0 = x_n = X, X(2^n-1)=sum a_i 2^{i-1}
        ll X; bool ok=true;
        if(n<=40){
            L B=0; for(int i=1;i<=n;i++) B+=(L)a[i]<<(i-1);
            L D=((L)1<<n)-1;
            if(B%D!=0) ok=false; else X=(ll)(B/D);
        } else {
            ll m=(1LL<<31); ll s=0;
            for(int i=1;i<=31;i++) s=(s+(a[i]%m)*((1LL<<(i-1))%m))%m;
            X=(m-s)%m;
        }
        ll mn=LLONG_MAX, sum=0;
        if(ok){
            ll x=X;
            for(int i=1;i<=n && ok;i++){
                ll tt=x+a[i];
                if(tt&1){ok=false;break;}
                x=tt/2; mn=min(mn,x); sum+=x;
            }
            if(ok && x!=X) ok=false;
            if(ok && mn<0) ok=false;
        }
        if(!ok) printf("-1\n");
        else printf("%lld\n", sum-(ll)n*mn);
    }
}

#include <bits/stdc++.h>
using namespace std;
int main(){
    int t; scanf("%d",&t);
    while(t--){
        int n; scanf("%d",&n);
        vector<int> a(n), b(n), deg(n+1,0);
        for(auto& x:a) scanf("%d",&x);
        for(auto& x:b) scanf("%d",&x);
        for(int i=0;i<n;i++){ deg[a[i]]++; deg[b[i]]++; }
        bool ok=true;
        for(int v=1;v<=n;v++) if(deg[v]&1) ok=false;
        if(!ok){ puts("-1"); continue; }
        // Euler orientation: edge i oriented a_i -> b_i after optional swap
        vector<vector<int>> adj(n+1);
        for(int i=0;i<n;i++){ adj[a[i]].push_back(i); adj[b[i]].push_back(i); }
        vector<char> used(n,0), sw(n,0);
        vector<size_t> ptr(n+1,0);
        for(int v=1;v<=n;v++){
            int cur=v;
            while(true){
                while(ptr[cur]<adj[cur].size() && used[adj[cur][ptr[cur]]]) ptr[cur]++;
                if(ptr[cur]==adj[cur].size()) break;
                int e=adj[cur][ptr[cur]++];
                used[e]=1;
                int nxt;
                if(a[e]==cur){ nxt=b[e]; } else { nxt=a[e]; sw[e]=1; }
                cur=nxt;
            }
        }
        vector<int> res;
        for(int i=0;i<n;i++) if(sw[i]) res.push_back(i+1);
        printf("%d\n", (int)res.size());
        for(size_t i=0;i<res.size();i++) printf("%d%c", res[i], i+1==res.size()?'\n':' ');
        if(res.empty()) printf("\n");
    }
}

#include <bits/stdc++.h>
using namespace std;
int main(){
    int t; scanf("%d",&t);
    while(t--){
        int n; scanf("%d",&n);
        vector<int> a(n), b(n), cid(n), pos(n), seen(n,0);
        vector<vector<int>> cyc;
        for(auto& x:a){ scanf("%d",&x); x--; }
        for(auto& x:b){ scanf("%d",&x); if(x>0) x--; }
        for(int i=0;i<n;i++) if(!seen[i]){
            int c=cyc.size(); cyc.push_back({});
            for(int x=i; !seen[x]; x=a[x]){ seen[x]=1; cid[x]=c; pos[x]=cyc[c].size(); cyc[c].push_back(x); }
        }
        int C=cyc.size(); bool ok=true;
        vector<int> tgt(C,-1), sh(C,0); vector<char> usedT(C,0);
        auto L=[&](int c){ return (int)cyc[c].size(); };
        auto md=[&](int v,int m){ return ((v%m)+m)%m; };
        for(int i=0;i<n && ok;i++) if(b[i]>=0){
            int c=cid[i], d=cid[b[i]], s=md(pos[b[i]]-pos[i],L(c));
            if(L(c)!=L(d) || (tgt[c]!=-1 && (tgt[c]!=d || sh[c]!=s))) ok=false;
            tgt[c]=d; sh[c]=s;
        }
        for(int c=0;c<C && ok;c++) if(tgt[c]>=0){ if(usedT[tgt[c]]) ok=false; usedT[tgt[c]]=1; }
        if(!ok){ puts("NO"); continue; }
        auto fill=[&](int c,int d,int s){ for(int j=0;j<L(c);j++) b[cyc[c][j]]=cyc[d][(j+s)%L(c)]; };
        auto mn=[&](int c){ return *min_element(cyc[c].begin(),cyc[c].end()); };
        vector<vector<int>> byLen(n+1); vector<size_t> ptr(n+1,0);
        for(int c=0;c<C;c++){ if(tgt[c]>=0) fill(c,tgt[c],sh[c]); byLen[L(c)].push_back(c); }
        for(auto& v:byLen) sort(v.begin(),v.end(),[&](int x,int y){return mn(x)<mn(y);});
        for(int i=0;i<n;i++) if(b[i]<0){
            int c=cid[i]; auto& lst=byLen[L(c)]; size_t& p=ptr[L(c)];
            while(usedT[lst[p]]) p++;
            int d=lst[p]; usedT[d]=1;
            fill(c,d,md(min_element(cyc[d].begin(),cyc[d].end())-cyc[d].begin()-pos[i],L(c)));
        }
        puts("YES");
        for(int i=0;i<n;i++) printf("%d%c", b[i]+1, i+1==n?'\n':' ');
    }
}
